578:export async function addPeriod(page: Page, f: { name: string; from: string; to: string }): Promise<boolean> {
579:  const all = page.locator('[data-testid^="period-row-"]');
581:  await page.getByTestId('period-form-name').fill(f.name);
582:  await page.getByTestId('period-form-from').fill(f.from);
583:  await page.getByTestId('period-form-to').fill(f.to);
584:  await page.getByTestId('period-form-submit').click();
585:  return until(page, async () => (await all.count()) > before, page.getByTestId('period-form-error'), 'add period');
588:/** Generate monthly periods between two dates: how many were made, or null when refused. */
589:export async function generatePeriods(page: Page, from: string, to: string): Promise<number | null> {
590:  await page.getByTestId('period-generate-from').fill(from);
591:  await page.getByTestId('period-generate-to').fill(to);
592:  const was = await shown(page.getByTestId('period-generated'));
593:  await page.getByTestId('period-generate').click();
595:  const ok = await until(page, async () => (await page.getByTestId('period-generated').count()) > 0
596:    && (await shown(page.getByTestId('period-generated'))) !== '' && ((await shown(page.getByTestId('period-generated'))) !== was || was === ''),
597:    page.getByTestId('period-generate-error'), 'generate periods');
